package com.configmonitor.app;
import android.app.*;import android.content.*;import android.media.*;import android.net.Uri;import android.os.*;import androidx.core.app.NotificationCompat;import java.util.*;
public final class Alerts {
 static final Handler handler=new Handler(Looper.getMainLooper());static final Set<Long> ids=new LinkedHashSet<>();static MediaPlayer player;static Vibrator vibrator;static int generation=0;static boolean fallbackTone=false;static long lastSoundAttempt=-5000;static volatile long lastRecovery=-5000;
 public static void channels(Context c){if(Build.VERSION.SDK_INT>=26){NotificationManager nm=c.getSystemService(NotificationManager.class);NotificationChannel low=new NotificationChannel("monitor","Monitoring",NotificationManager.IMPORTANCE_LOW);low.setDescription("Visible while health checks run");nm.createNotificationChannel(low);NotificationChannel high=new NotificationChannel("outage","Config alerts",NotificationManager.IMPORTANCE_HIGH);high.setDescription("Configurable monitor alerts");high.setSound(null,null);high.setLockscreenVisibility(Notification.VISIBILITY_PRIVATE);if(nm.isNotificationPolicyAccessGranted())high.setBypassDnd(true);nm.createNotificationChannel(high);}}
 public static void restore(){if(isActive())return;try{org.json.JSONArray saved=new org.json.JSONArray(App.prefs.getString("alarmIds","[]"));for(int i=0;i<saved.length();i++)raise(saved.getLong(i));}catch(Exception ignored){}}
 static void persist(){org.json.JSONArray a=new org.json.JSONArray();synchronized(ids){for(long id:ids)a.put(id);}App.prefs.edit().putString("alarmIds",a.toString()).apply();}
 public static boolean isActive(){synchronized(ids){return !ids.isEmpty();}}
 public static String names(){StringBuilder b=new StringBuilder();synchronized(ids){for(long id:ids){if(b.length()>0)b.append("\n");if(id==-1)b.append(App.t("آزمایش زنگ هشدار","Alarm test"));else if(id==0)b.append(App.t("اینترنت گوشی در دسترس نیست","Device network unavailable"));else{org.json.JSONObject m=App.db.get(id);if(m!=null)b.append(m.optString("name")).append(m.optString("incidentReason").equals("latency")?App.t(" • تأخیر بالا"," • high latency"):App.t(" • بدون پاسخ"," • no response"));}}}return b.toString();}
 public static boolean allowed(long id){if(id<0)return true;long now=System.currentTimeMillis();AlertSchedule.Window window=AlertPolicy.window(now);if(!window.active)return false;if(id==0)return App.prefs.getLong("networkSnoozeUntil",0)<=now;org.json.JSONObject n=App.db.get(id);return AlertSchedule.deliver(n,window,now);}
 public static void raise(long id){handler.post(()->{if(!allowed(id))return;boolean first;synchronized(ids){first=ids.isEmpty();ids.add(id);}persist();App.prefs.edit().putBoolean("alarmActive",true).apply();
  AlarmDelivery.run(Alerts::ensureSound,()->{if(first&&App.prefs.getBoolean("vibrate",true)){vibrator=(Vibrator)App.app.getSystemService(Context.VIBRATOR_SERVICE);if(vibrator!=null){long[] pattern={0,500,600,500,1400};if(Build.VERSION.SDK_INT>=26)vibrator.vibrate(VibrationEffect.createWaveform(pattern,0),new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).build());else vibrator.vibrate(pattern,0);}}},Alerts::notifyAlarm,()->{if(MainActivity.visible)App.app.startActivity(new Intent(App.app,AlarmActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));});App.update();});}
 /** Repair a process-death/posting gap and recover a failed audio player without repeating acknowledged alarms. */
 public static void reconcile(){handler.post(Alerts::enforcePolicy);long elapsed=SystemClock.elapsedRealtime();if(elapsed-lastRecovery<5000)return;lastRecovery=elapsed;handler.post(()->{
  if(App.prefs.getBoolean("running",false)){org.json.JSONArray nodes=App.db.all();long now=System.currentTimeMillis();for(int i=0;i<nodes.length();i++){org.json.JSONObject node=nodes.optJSONObject(i);if(node==null)continue;long id=node.optLong("id");boolean present;synchronized(ids){present=ids.contains(id);}if(!present&&AlertSchedule.deliver(node,AlertPolicy.window(now),now))raise(id);}}
  ensureSound();
 });}
 public static void policyChanged(){lastRecovery=-5000;reconcile();}
 static void enforcePolicy(){if(AlertPolicy.window(System.currentTimeMillis()).active)return;boolean changed,empty;synchronized(ids){changed=ids.removeIf(id->id>=0);empty=ids.isEmpty();}if(!changed)return;if(empty)stopNow();else{persist();AlarmDelivery.run(Alerts::notifyAlarm);App.update();}}
 static void ensureSound(){boolean playing=false;if(player!=null)try{playing=player.isPlaying();}catch(RuntimeException ignored){}long now=SystemClock.elapsedRealtime();if(AlarmRecovery.retryAudio(isActive(),playing,now,lastSoundAttempt))sound();}
 private static void notifyAlarm(){NotificationManager nm=App.app.getSystemService(NotificationManager.class);PendingIntent open=PendingIntent.getActivity(App.app,5,new Intent(App.app,AlarmActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent ack=PendingIntent.getBroadcast(App.app,6,new Intent(App.app,Actions.class).setAction("ack"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent snooze=PendingIntent.getBroadcast(App.app,8,new Intent(App.app,Actions.class).setAction("snooze"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification note=new NotificationCompat.Builder(App.app,"outage").setSmallIcon(R.drawable.ic_notification).setContentTitle(App.t("هشدار پایش","Monitor alert")).setContentText(names()).setStyle(new NotificationCompat.BigTextStyle().bigText(names())).setPriority(NotificationCompat.PRIORITY_MAX).setCategory(NotificationCompat.CATEGORY_ALARM).setVisibility(NotificationCompat.VISIBILITY_PRIVATE).setOngoing(true).setFullScreenIntent(open,true).setContentIntent(open).addAction(0,App.t("متوجه شدم","Got it"),ack).addAction(0,App.t("تعویق ۱۵ دقیقه","Snooze 15 min"),snooze).build();nm.notify(2,note);}
 static void sound(){
  lastSoundAttempt=SystemClock.elapsedRealtime();generation++;if(player!=null){try{player.release();}catch(RuntimeException ignored){}player=null;}
  float volume=App.prefs.getInt("volume",80)/100f;boolean gradual=App.prefs.getBoolean("gradual",false);float initial=gradual?Math.min(.08f,volume):volume;
  String selected=fallbackTone?"builtin:gentle":App.prefs.getString("tone","builtin:gentle");
  for(String tone:new String[]{selected,"builtin:gentle"}){MediaPlayer candidate=null;try{
   candidate=AlarmAudio.create(App.app,tone,true,initial);final MediaPlayer current=candidate;
   candidate.setOnErrorListener((failed,what,extra)->{if(player==current){player=null;fallbackTone=true;generation++;}try{failed.release();}catch(RuntimeException ignored){}return true;});
   player=candidate;candidate.start();break;
  }catch(Exception e){if(candidate!=null)try{candidate.release();}catch(RuntimeException ignored){}player=null;}}
  if(player==null)return;int token=++generation;if(gradual)for(int step=1;step<=10;step++){final float level=volume*step/10f;handler.postDelayed(()->{if(token==generation&&player!=null)try{player.setVolume(level,level);}catch(Exception ignored){}},step*1000L);}
 }

 public static void stop(){handler.post(Alerts::stopNow);}
 private static void stopNow(){fallbackTone=false;lastSoundAttempt=-5000;synchronized(ids){ids.clear();}persist();App.prefs.edit().putBoolean("alarmActive",false).apply();generation++;if(player!=null){try{player.stop();}catch(Exception ignored){}player.release();player=null;}if(vibrator!=null)vibrator.cancel();App.app.getSystemService(NotificationManager.class).cancel(2);App.update();}
 public static void dismiss(long id){handler.post(()->{boolean empty;synchronized(ids){ids.remove(id);empty=ids.isEmpty();}persist();if(empty)stopNow();else AlarmDelivery.run(Alerts::notifyAlarm);});}
 public static void snooze(){handler.post(()->{List<Long> active;synchronized(ids){active=new ArrayList<>(ids);}long until=System.currentTimeMillis()+15*60*1000L;for(long id:active){if(id==0)App.prefs.edit().putLong("networkSnoozeUntil",until).apply();else if(id>0)try{App.db.suppress(id,"snoozeUntil",until);}catch(Exception ignored){}}stopNow();});}
 public static void acknowledge(){handler.post(()->{Set<Long> active;synchronized(ids){active=new HashSet<>(ids);}App.db.acknowledge(active);stopNow();});}
}
